import { useSyncExternalStore } from 'react'
import { dataService, type DataService, type DataServiceState } from '../../services/data/data_service'

const snapshots = new WeakMap<DataService, DataServiceState>()

function isSameDataServiceState(first: DataServiceState, second: DataServiceState) {
    return first.project === second.project
        && first.runningAgents === second.runningAgents
        && first.snapshot === second.snapshot
}

function getProjectStateSnapshot(service: DataService): DataServiceState {
    const nextSnapshot = service.getState()
    const currentSnapshot = snapshots.get(service)
    if (currentSnapshot && isSameDataServiceState(currentSnapshot, nextSnapshot)) return currentSnapshot

    snapshots.set(service, nextSnapshot)

    return nextSnapshot
}

export function useProjectState(service: DataService = dataService): DataServiceState {
    return useSyncExternalStore(
        (onStoreChange) => {
            service.addEventListener('changed', onStoreChange)

            return () => service.removeEventListener('changed', onStoreChange)
        },
        () => getProjectStateSnapshot(service),
        () => getProjectStateSnapshot(service),
    )
}

import { describe, expect, it } from 'vitest'
import type { ProjectReference } from '../../../data/data_types'
import { projectName } from './project_name'

describe('projectName', () => {
    it.each([
        ['C:\\work\\md2_workers\\', 'md2_workers'],
        ['/work/md2_workers/', 'md2_workers'],
        ['C:/work\\md2_workers', 'md2_workers'],
    ])('uses the final folder segment from %s', (rootPath, expectedName) => {
        expect(projectName({ branch: 'main', id: 'full-project-id', rootPath })).toBe(expectedName)
    })

    it('uses the repository for a GitHub project', () => {
        const project: ProjectReference = {
            branch: 'main',
            id: 'owner/full-project-id',
            owner: 'owner',
            repository: 'md2_workers',
        }

        expect(projectName(project)).toBe('md2_workers')
    })

    it('fails clearly when a local or remote project has no rootPath', () => {
        expect(() => projectName({ branch: 'main', id: 'full-project-id' }))
            .toThrow('Cannot derive local or remote project name without rootPath')
    })

    it('fails clearly when a GitHub project has no repository', () => {
        expect(() => projectName({ branch: 'main', id: 'owner/full-project-id', owner: 'owner' }))
            .toThrow('Cannot derive GitHub project name without repository')
    })
})

import { act, cleanup, render, screen } from '@testing-library/react'
import { afterEach, describe, expect, it } from 'vitest'
import type { ProjectReference } from '../../../data/data_types'
import type { DataService, DataServiceState } from '../../../services/data/data_service'
import { AppThemeProvider } from '../../../theme/theme_provider'
import { ProjectNameLabel } from './project_name_label'

const EMPTY_STATE: DataServiceState = {
    project: null,
    runningAgents: [],
    snapshot: null,
}

class TestDataService extends EventTarget {
    private state: DataServiceState = EMPTY_STATE

    getState() {
        return this.state
    }

    setProject(project: ProjectReference | null) {
        this.state = { ...this.state, project }
        this.dispatchEvent(new Event('changed'))
    }
}

function renderProjectNameLabel(service: TestDataService) {
    return render(
        <AppThemeProvider>
            <ProjectNameLabel service={service as unknown as DataService} />
        </AppThemeProvider>,
    )
}

describe('ProjectNameLabel', () => {
    afterEach(cleanup)

    it('renders nothing when no project is open', () => {
        const service = new TestDataService()
        const { container } = renderProjectNameLabel(service)

        expect(container).toBeEmptyDOMElement()
    })

    it('updates when the active project changes', () => {
        const service = new TestDataService()
        service.setProject({ branch: 'main', id: 'C:/first-project', rootPath: 'C:/first-project' })
        renderProjectNameLabel(service)

        expect(screen.getByText('first-project')).toBeInTheDocument()

        act(() => service.setProject({
            branch: 'main',
            id: 'owner/second-project',
            owner: 'owner',
            repository: 'second-project',
        }))

        expect(screen.getByText('second-project')).toBeInTheDocument()
        expect(screen.queryByText('first-project')).toBeNull()
    })

    it('keeps constrained project names on one truncating line', () => {
        const service = new TestDataService()
        service.setProject({
            branch: 'main',
            id: 'C:/work/a-very-long-project-name',
            rootPath: 'C:/work/a-very-long-project-name',
        })
        renderProjectNameLabel(service)

        expect(screen.getByTestId('project-name-label')).toHaveStyle({
            minWidth: '0',
            overflow: 'hidden',
            textOverflow: 'ellipsis',
            whiteSpace: 'nowrap',
        })
    })
})

